-- Cours élémentaire, leçon 1 : indices des petits QCM des pages 1.1 à 1.5 (sql/69, #1114). Quand l'élève choisit une
-- mauvaise proposition, le site et l'application affichent « Mauvaise réponse : » suivi de l'indice de cette proposition
-- ("indices" : un texte par proposition, dans l'ordre ; "" pour la bonne réponse).
SET NAMES utf8mb4;

UPDATE lecioneroj le JOIN lecionoj l ON l.id = le.leciono_id
SET le.enhavo = REPLACE(le.enhavo, '[{"question": "Écoutez et choisissez comment s’écrit ce mot&nbsp;: <a href=''fr/son/vortoj/cxokolado.mp3'' class=''sm2_button''></a>", "propositions": ["ŝokolado", "ĉokolado", "cokolado"], "indices": ["", ""], "reponse": 2}, {"question": "Écoutez et choisissez comment s’écrit ce mot&nbsp;: <a href=''fr/son/vortoj/jxurnalo.mp3'' class=''sm2_button''></a>", "propositions": ["ĝurnalo", "jurnalo", "ĵurnalo"], "indices": ["", ""], "reponse": 3}, {"question": "Écoutez et choisissez comment s’écrit ce mot&nbsp;: <a href=''fr/son/vortoj/knabo.mp3'' class=''sm2_button''></a>", "propositions": ["knabo", "kanbo", "nabo"], "indices": ["", ""], "reponse": 1}]', '[{"question": "Écoutez et choisissez comment s’écrit ce mot&nbsp;: <a href=''fr/son/vortoj/cxokolado.mp3'' class=''sm2_button''></a>", "propositions": ["ŝokolado", "ĉokolado", "cokolado"], "indices": ["ŝ se prononce « ch », comme dans « chaud ».", "", "c se prononce « ts », comme dans « tsar »."], "reponse": 2}, {"question": "Écoutez et choisissez comment s’écrit ce mot&nbsp;: <a href=''fr/son/vortoj/jxurnalo.mp3'' class=''sm2_button''></a>", "propositions": ["ĝurnalo", "jurnalo", "ĵurnalo"], "indices": ["ĝ se prononce « dj », comme dans « Djibouti ».", "j se prononce « y », comme dans « yogourt ».", ""], "reponse": 3}, {"question": "Écoutez et choisissez comment s’écrit ce mot&nbsp;: <a href=''fr/son/vortoj/knabo.mp3'' class=''sm2_button''></a>", "propositions": ["knabo", "kanbo", "nabo"], "indices": ["", "écoutez bien l’ordre des sons : k-n-a-b-o.", "en espéranto, toutes les lettres se prononcent, même le k devant le n."], "reponse": 1}]')
WHERE l.kurso = 'CG' AND l.numero = 1 AND le.ordo = 1;

UPDATE lecioneroj le JOIN lecionoj l ON l.id = le.leciono_id
SET le.enhavo = REPLACE(le.enhavo, '[{"question": "Le mot <span class=''eo''>kafo</span> est…", "propositions": ["un adjectif", "un nom", "un verbe à l’infinitif"], "indices": ["", ""], "reponse": 2}, {"question": "Lequel de ces mots est un adjectif&nbsp;?", "propositions": ["pano", "esti", "bela"], "indices": ["", ""], "reponse": 3}, {"question": "Comment dit-on «&nbsp;un bon café&nbsp;»&nbsp;?", "propositions": ["bona kafo", "bono kafa", "bona kafa"], "indices": ["", ""], "reponse": 1}]', '[{"question": "Le mot <span class=''eo''>kafo</span> est…", "propositions": ["un adjectif", "un nom", "un verbe à l’infinitif"], "indices": ["les adjectifs finissent par -a (bela, bona).", "", "les verbes à l’infinitif finissent par -i (esti)."], "reponse": 2}, {"question": "Lequel de ces mots est un adjectif&nbsp;?", "propositions": ["pano", "esti", "bela"], "indices": ["pano finit par -o : c’est un nom (le pain).", "esti finit par -i : c’est un verbe (être).", ""], "reponse": 3}, {"question": "Comment dit-on «&nbsp;un bon café&nbsp;»&nbsp;?", "propositions": ["bona kafo", "bono kafa", "bona kafa"], "indices": ["", "le nom (café) finit par -o et l’adjectif (bon) par -a.", "presque ! Le nom café finit par -o : kafo."], "reponse": 1}]')
WHERE l.kurso = 'CG' AND l.numero = 1 AND le.ordo = 2;

UPDATE lecioneroj le JOIN lecionoj l ON l.id = le.leciono_id
SET le.enhavo = REPLACE(le.enhavo, '[{"question": "Que veut dire <span class=''eo''>patrino</span>&nbsp;?", "propositions": ["père", "mère", "sœur"], "indices": ["", ""], "reponse": 2}, {"question": "Quel mot veut dire «&nbsp;gâteau&nbsp;»&nbsp;?", "propositions": ["kafo", "lakto", "kuko"], "indices": ["", ""], "reponse": 3}, {"question": "<span class=''eo''>frato</span> et <span class=''eo''>fratino</span>, ce sont…", "propositions": ["le frère et la sœur", "le père et la mère", "le fils et la fille"], "indices": ["", ""], "reponse": 1}]', '[{"question": "Que veut dire <span class=''eo''>patrino</span>&nbsp;?", "propositions": ["père", "mère", "sœur"], "indices": ["père se dit patro. Regardez la fin du mot : patr-in-o.", "", "sœur se dit fratino."], "reponse": 2}, {"question": "Quel mot veut dire «&nbsp;gâteau&nbsp;»&nbsp;?", "propositions": ["kafo", "lakto", "kuko"], "indices": ["kafo, c’est le café.", "lakto, c’est le lait.", ""], "reponse": 3}, {"question": "<span class=''eo''>frato</span> et <span class=''eo''>fratino</span>, ce sont…", "propositions": ["le frère et la sœur", "le père et la mère", "le fils et la fille"], "indices": ["", "père et mère se disent patro et patrino.", "fils et fille se disent filo et filino."], "reponse": 1}]')
WHERE l.kurso = 'CG' AND l.numero = 1 AND le.ordo = 3;

UPDATE lecioneroj le JOIN lecionoj l ON l.id = le.leciono_id
SET le.enhavo = REPLACE(le.enhavo, '[{"question": "Pour parler de Maria, on dit…", "propositions": ["li", "ŝi", "ĝi"], "indices": ["", ""], "reponse": 2}, {"question": "Pour parler du gâteau (<span class=''eo''>la kuko</span>), on dit…", "propositions": ["ĝi", "ŝi", "li"], "indices": ["", ""], "reponse": 1}, {"question": "Comment dit-on «&nbsp;nous sommes&nbsp;»&nbsp;?", "propositions": ["mi estas", "ni estis", "ni estas"], "indices": ["", ""], "reponse": 3}, {"question": "Comment dit-on «&nbsp;mon ami&nbsp;»&nbsp;?", "propositions": ["mi amiko", "mia amiko", "mia amika"], "indices": ["", ""], "reponse": 2}]', '[{"question": "Pour parler de Maria, on dit…", "propositions": ["li", "ŝi", "ĝi"], "indices": ["li, c’est pour un homme ou un garçon.", "", "ĝi, c’est pour une chose ou un animal."], "reponse": 2}, {"question": "Pour parler du gâteau (<span class=''eo''>la kuko</span>), on dit…", "propositions": ["ĝi", "ŝi", "li"], "indices": ["", "ŝi, c’est pour une femme ou une fille. Pour une chose, on dit ĝi.", "li, c’est pour un homme. Pour une chose, on dit ĝi."], "reponse": 1}, {"question": "Comment dit-on «&nbsp;nous sommes&nbsp;»&nbsp;?", "propositions": ["mi estas", "ni estis", "ni estas"], "indices": ["mi, c’est « je ». « Nous » se dit ni.", "presque ! -is, c’est le passé (nous étions). Le présent finit par -as.", ""], "reponse": 3}, {"question": "Comment dit-on «&nbsp;mon ami&nbsp;»&nbsp;?", "propositions": ["mi amiko", "mia amiko", "mia amika"], "indices": ["presque ! Pour dire « mon », on ajoute -a à mi : mia.", "", "ami est un nom, il finit par -o : amiko."], "reponse": 2}]')
WHERE l.kurso = 'CG' AND l.numero = 1 AND le.ordo = 4;

UPDATE lecioneroj le JOIN lecionoj l ON l.id = le.leciono_id
SET le.enhavo = REPLACE(le.enhavo, '[{"question": "<span class=''eo''>Ŝia pano estis seka.</span> Le pain est à…", "propositions": ["lui", "nous", "elle"], "indices": ["", ""], "reponse": 3}, {"question": "<span class=''eo''>Iliaj kafoj estos varmaj.</span> Les cafés seront…", "propositions": ["chauds", "froids", "secs"], "indices": ["", ""], "reponse": 1}, {"question": "<span class=''eo''>La knaboj estas grandaj.</span> Combien y a-t-il de garçons&nbsp;?", "propositions": ["un seul", "plusieurs"], "indices": [""], "reponse": 2}]', '[{"question": "<span class=''eo''>Ŝia pano estis seka.</span> Le pain est à…", "propositions": ["lui", "nous", "elle"], "indices": ["« à lui » se dit lia. Ŝia vient de ŝi (elle).", "« à nous » se dit nia.", ""], "reponse": 3}, {"question": "<span class=''eo''>Iliaj kafoj estos varmaj.</span> Les cafés seront…", "propositions": ["chauds", "froids", "secs"], "indices": ["", "varma veut dire chaud.", "sec se dit seka."], "reponse": 1}, {"question": "<span class=''eo''>La knaboj estas grandaj.</span> Combien y a-t-il de garçons&nbsp;?", "propositions": ["un seul", "plusieurs"], "indices": ["le -j de knaboj et de grandaj indique le pluriel.", ""], "reponse": 2}]')
WHERE l.kurso = 'CG' AND l.numero = 1 AND le.ordo = 5;
